def main():
 OUT.mkdir(exist_ok=False);pack=json.loads((P/'humanize-source-pack-v1.json').read_text());runtime=json.loads((P/'humanize-confined-runtime-results-v1.json').read_text())
 selected=['v1.0.1:'+x for x in ['ParseBytes','ParseBigBytes','BigBytes','BigIBytes','humanateBigBytes','oomm','BigComma','ParseSI','ComputeSI']]
