 criteria=['Exactly two unique complete chapter languages and requested sections','Fixed-width float64 precision and big.Rat integer preservation/truncation distinguished','New R/Q support limited to big byte API; fixed-width parser unchanged','BigComma mutates caller input while big formatter copies it','ParseSI magnitude/unit split correctly distinguished from byte parsing','35/36 exact predictions per cut and ComputeSI mismatch interpreted honestly','Source/runtime context, module directive and illustrative command/example scopes accurate','EN/PT code/units/numbers and relevant FAQ answers agree; no invented guarantees']
 protocol={'at':now(),'hypothesis':'A new Go family with exact source and bounded runtime evidence may support a complete bilingual chapter across precision, mutable-input ownership and API-specific unit changes. This is a new task, not a retry of prior rejected families.','maximum_calls':1,'no_retries':True,'task':'COMPACT_BILINGUAL_GO_CHAPTER_FROM_SOURCE_AND_OWNED_OBSERVATIONS','repository':'dustin/go-humanize','development_exposed':True,'certified_neural_holdout':False,'baseline_name_hits':0,'evidence_ids':selected,'observation_case_ids':sorted(ids),'schema':schema,'system':system,'acceptance_criteria':criteria,'deterministic_comparator':'humanize-chapter-ledger-v1.json','deterministic_comparator_sha256':hashlib.sha256((P/'humanize-chapter-ledger-v1.json').read_bytes()).hexdigest(),'comparison_limits':'Deterministic chapter frozen before dispatch but longer and source-reviewed by Codex; no independent human grading, equal-effort comparison or causal neural-gain claim.','resource_budget':{'maximum_output_tokens':2400,'context_tokens':8192,'maximum_request_bytes':24576,'http_timeout_seconds':1800,'num_thread':4,'keep_alive':0},'model':'llama3.2:3b','digest':'a80c4f17acd55265feec403c7aef86be0c25983ab279d83f3bcd3abbcb5b8b72','training':False,'publication':False,'transport_sha256':hashlib.sha256(TRANSPORT.read_bytes()).hexdigest()}
 save('protocol.json',protocol);tags=json.loads(transport.request('/api/tags',timeout=15));matches=[m for m in tags['models']if m['name']==protocol['model']];assert len(matches)==1 and matches[0]['digest']==protocol['digest'];save('model-observation.json',{'at':now(),'name':matches[0]['name'],'digest':matches[0]['digest']})
 request={'model':protocol['model'],'stream':False,'keep_alive':0,'format':schema,'options':{'temperature':0,'seed':42,'num_ctx':8192,'num_predict':2400,'num_thread':4},'messages':[{'role':'system','content':system},{'role':'user','content':json.dumps({'source_evidence':evidence,'owned_observations':observations,'review':'36 frozen distinct cases observed once in each revision, 35 exact owned predictions matched per cut. Fixed-width bytes.go hashes are identical across both cuts. No compatibility across operating systems, universal numerical accuracy or mutable-global safety was tested.'},ensure_ascii=False)}]}
 payload=json.dumps(request,ensure_ascii=False).encode();assert len(payload)<=24576;save('request.json',request);save('dispatch.json',{'at':now(),'status':'DISPATCHING_DO_NOT_RETRY','request_sha256':hashlib.sha256(payload).hexdigest(),'bytes':len(payload)})
 start=time.monotonic()
 try:
  raw=transport.request('/api/chat',payload,timeout=1800)
  with(OUT/'response.json').open('xb')as f:f.write(raw);f.flush();os.fsync(f.fileno())
  r=json.loads(raw);save('outcome.json',{'at':now(),'status':'PRESERVED_PENDING_FACTUAL_REVIEW','wall_seconds':time.monotonic()-start,'model_seconds':r.get('total_duration',0)/1e9,'done':r.get('done'),'done_reason':r.get('done_reason'),'generated_tokens':r.get('eval_count'),'prompt_tokens':r.get('prompt_eval_count'),'owner_approved':False,'training_gold':False});print('One new Go chapter response preserved; factual review pending.',flush=True)
 except Exception as error:
  save('error.json',{'at':now(),'status':'UNCERTAIN_NO_RETRY','wall_seconds':time.monotonic()-start,'error':str(error)[:1000]});raise
